// Các ví dụ minh họa về Big O

// O(1) - Thời gian hằng số (không phụ thuộc kích thước mảng)
function getFirst(arr) {
  return arr[0];
}

// O(log n) - Logarit: Tìm kiếm nhị phân (chia đôi tập tìm kiếm mỗi bước)
function binarySearch(arr, target) {
  let left = 0, right = arr.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return -1;
}

// O(n) - Tuyến tính: Duyệt qua mảng 1 lần
function findMax(arr) {
  let max = arr[0];
  for (const num of arr) {
    if (num > max) max = num;
  }
  return max;
}

// O(n log n) - Tuyến tính x Logarit: Merge Sort
function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  return merge(left, right);
}

// O(n²) - Bậc hai: 2 vòng lặp lồng nhau (Bubble Sort)
function bubbleSort(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = 0; j < arr.length - i - 1; j++)
      if (arr[j] > arr[j+1]) [arr[j], arr[j+1]] = [arr[j+1], arr[j]];
  return arr;
}

// 1. Two Pointers - Tìm cặp phần tử có tổng bằng target trên mảng đã sắp xếp
function twoSum(sorted, target) {
  let left = 0, right = sorted.length - 1;
  while (left < right) {
    const sum = sorted[left] + sorted[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;
    else right--;
  }
  return [-1, -1];
}

// 2. Sliding Window - Tìm tổng mảng con lớn nhất có độ dài k
function maxSubarraySum(arr, k) {
  let windowSum = 0;
  for (let i = 0; i < k; i++) windowSum += arr[i];
  let maxSum = windowSum;
  for (let i = k; i < arr.length; i++) {
    windowSum += arr[i] - arr[i - k]; // Trượt cửa sổ sang phải
    maxSum = Math.max(maxSum, windowSum);
  }
  return maxSum;
}

// 3. Frequency Map - Đếm tần suất xuất hiện của ký tự
function mostFrequent(arr) {
  const freq = {};
  let maxCount = 0, result = null;
  for (const item of arr) {
    freq[item] = (freq[item] || 0) + 1;
    if (freq[item] > maxCount) {
      maxCount = freq[item];
      result = item;
    }
  }
  return result;
}

// 4. Prefix Sum - Mảng cộng dồn giúp truy vấn tổng đoạn [i..j] trong O(1)
function prefixSum(arr) {
  const prefix = [0];
  for (const num of arr) prefix.push(prefix.at(-1) + num);
  return (i, j) => prefix[j + 1] - prefix[i];
}

// Khởi tạo Node trong Linked List
class ListNode {
  constructor(val, next = null) {
    this.val = val;
    this.next = next;
  }
}

// Đảo ngược danh sách liên kết
function reverseList(head) {
  let prev = null, curr = head;
  while (curr) {
    const next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  return prev;
}

// Phát hiện chu trình (Floyd's Cycle Finding Algorithm)
function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

// Stack - Kiểm tra dấu đóng mở ngoặc hợp lệ
function isValid(s) {
  const stack = [];
  const map = { ")": "(", "]": "[", "}": "{" };
  for (const char of s) {
    if ("({[".includes(char)) stack.push(char);
    else if (stack.pop() !== map[char]) return false;
  }
  return stack.length === 0;
}

// Hash Map: Bài toán Two Sum kinh điển
function twoSum(nums, target) {
  const map = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (map.has(complement)) return [map.get(complement), i];
    map.set(nums[i], i);
  }
  return [-1, -1];
}

// Nhóm các từ đảo chữ (Group Anagrams)
function groupAnagrams(strs) {
  const map = new Map();
  for (const s of strs) {
    const key = [...s].sort().join("");
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(s);
  }
  return [...map.values()];
}

// Bộ nhớ đệm LRU Cache
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
  }
  get(key) {
    if (!this.cache.has(key)) return -1;
    const val = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, val);
    return val;
  }
  put(key, value) {
    this.cache.delete(key);
    this.cache.set(key, value);
    if (this.cache.size > this.capacity) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
  }
}

class TreeNode {
  constructor(val, left = null, right = null) {
    this.val = val;
    this.left = left;
    this.right = right;
  }
}

// Duyệt cây DFS Inorder (Trái -> Gốc -> Phải: cho thứ tự tăng dần trên BST)
function inorder(root, result = []) {
  if (!root) return result;
  inorder(root.left, result);
  result.push(root.val);
  inorder(root.right, result);
  return result;
}

// Duyệt cây BFS theo từng tầng (Level Order Traversal)
function levelOrder(root) {
  if (!root) return [];
  const result = [], queue = [root];
  while (queue.length) {
    const level = [];
    const size = queue.length;
    for (let i = 0; i < size; i++) {
      const node = queue.shift();
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
  }
  return result;
}

// Tính độ sâu tối đa của cây (Max Depth)
function maxDepth(root) {
  if (!root) return 0;
  return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

// Đệ quy có nhớ: Tính dãy Fibonacci (O(n) thay vì O(2ⁿ))
function fib(n, memo = {}) {
  if (n <= 1) return n;
  if (memo[n]) return memo[n];
  memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
  return memo[n];
}

// Quay lui: Sinh tất cả các tập con (Subsets)
function subsets(nums) {
  const result = [];
  function backtrack(start, current) {
    result.push([...current]);
    for (let i = start; i < nums.length; i++) {
      current.push(nums[i]);      // Chọn (Choose)
      backtrack(i + 1, current);  // Thử nghiệm (Explore)
      current.pop();              // Hủy chọn (Backtrack)
    }
  }
  backtrack(0, []);
  return result;
}

// Biểu diễn đồ thị bằng Danh sách kề (Adjacency List)
function buildGraph(edges) {
  const graph = {};
  for (const [u, v] of edges) {
    if (!graph[u]) graph[u] = [];
    if (!graph[v]) graph[v] = [];
    graph[u].push(v);
    graph[v].push(u);
  }
  return graph;
}

// BFS: Tìm đường đi ngắn nhất giữa hai đỉnh
function shortestPath(graph, start, end) {
  const queue = [[start, [start]]];
  const visited = new Set([start]);
  while (queue.length) {
    const [node, path] = queue.shift();
    if (node === end) return path;
    for (const neighbor of (graph[node] || [])) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push([neighbor, [...path, neighbor]]);
      }
    }
  }
  return null;
}

// DFS: Đếm số vùng liên thông (Connected Components)
function countComponents(n, edges) {
  const graph = buildGraph(edges);
  const visited = new Set();
  let count = 0;
  for (let i = 0; i < n; i++) {
    if (!visited.has(i)) {
      dfs(graph, i, visited);
      count++;
    }
  }
  return count;
}
function dfs(graph, node, visited) {
  visited.add(node);
  for (const neighbor of (graph[node] || [])) {
    if (!visited.has(neighbor)) dfs(graph, neighbor, visited);
  }
}

// 1D DP: Bài toán leo cầu thang (Climbing Stairs)
function climbStairs(n) {
  if (n <= 2) return n;
  let prev2 = 1, prev1 = 2;
  for (let i = 3; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

// 1D DP: Đổi tiền với số đồng xu ít nhất (Coin Change)
function coinChange(coins, amount) {
  const dp = Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (let i = 1; i <= amount; i++) {
    for (const coin of coins) {
      if (coin <= i) dp[i] = Math.min(dp[i], dp[i - coin] + 1);
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount];
}

// 2D DP: Chuỗi con chung dài nhất (Longest Common Subsequence)
function longestCommonSubsequence(text1, text2) {
  const m = text1.length, n = text2.length;
  const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (text1[i-1] === text2[j-1]) {
        dp[i][j] = dp[i-1][j-1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]);
      }
    }
  }
  return dp[m][n];
}

// Min Heap: Hàng đợi ưu tiên phần tử nhỏ nhất
class MinHeap {
  #data = [];
  get size() { return this.#data.length; }
  peek() { return this.#data[0]; }

  push(val) {
    this.#data.push(val);
    this.#bubbleUp(this.#data.length - 1);
  }

  pop() {
    const min = this.#data[0];
    const last = this.#data.pop();
    if (this.#data.length) {
      this.#data[0] = last;
      this.#bubbleDown(0);
    }
    return min;
  }

  #bubbleUp(i) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (this.#data[parent] <= this.#data[i]) break;
      [this.#data[parent], this.#data[i]] = [this.#data[i], this.#data[parent]];
      i = parent;
    }
  }

  #bubbleDown(i) {
    while (2 * i + 1 < this.#data.length) {
      let smallest = 2 * i + 1;
      if (smallest + 1 < this.#data.length && this.#data[smallest+1] < this.#data[smallest])
        smallest++;
      if (this.#data[i] <= this.#data[smallest]) break;
      [this.#data[i], this.#data[smallest]] = [this.#data[smallest], this.#data[i]];
      i = smallest;
    }
  }
}

// Trie: Cây tiền tố phục vụ Autocomplete
class Trie {
  constructor() { this.root = {}; }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node[ch]) node[ch] = {};
      node = node[ch];
    }
    node.isEnd = true;
  }
  search(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node[ch]) return false;
      node = node[ch];
    }
    return !!node.isEnd;
  }
  startsWith(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node[ch]) return false;
      node = node[ch];
    }
    return true;
  }
}

// Mẫu: Hợp nhất các khoảng thời gian bị chồng chéo (Merge Intervals)
function merge(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);
  const merged = [intervals[0]];
  for (let i = 1; i < intervals.length; i++) {
    const last = merged.at(-1);
    if (intervals[i][0] <= last[1]) {
      last[1] = Math.max(last[1], intervals[i][1]);
    } else {
      merged.push(intervals[i]);
    }
  }
  return merged;
}

// Mẫu: Con trỏ Nhanh & Chậm (Tìm trung điểm Linked List)
function findMiddle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
  }
  return slow;
}

